// WebSocket Server with TLS 1.3
// Implements SRS §3.1.2 (WebSocket Framing) and §3.2.1 (Transport Security)

pub mod connection;
pub mod error;
pub mod tls;
pub mod handler;

pub use error::{ServerError, Result};
pub use tls::TlsConfig;

use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio_rustls::TlsAcceptor;
use tracing::{info, warn, error};

use crate::session::manager::SessionManager;

/// WebSocket server configuration
#[derive(Debug, Clone)]
pub struct ServerConfig {
    /// Server bind address
    pub bind_addr: SocketAddr,

    /// TLS configuration
    pub tls: TlsConfig,

    /// Maximum concurrent connections (SRS §2.3.4: 1000 global limit)
    pub max_connections: usize,

    /// Connection rate limit (SRS §2.3.4: 100/minute)
    pub rate_limit_per_minute: u32,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            bind_addr: "127.0.0.1:8443".parse().unwrap(),
            tls: TlsConfig::default(),
            max_connections: 1000,
            rate_limit_per_minute: 100,
        }
    }
}

/// WebSocket server with TLS 1.3 support
pub struct Server {
    config: ServerConfig,
    session_manager: Arc<SessionManager>,
    tls_acceptor: TlsAcceptor,
}

impl Server {
    /// Create a new WebSocket server
    pub fn new(config: ServerConfig, session_manager: Arc<SessionManager>) -> Result<Self> {
        let tls_acceptor = config.tls.build_acceptor()?;

        Ok(Self {
            config,
            session_manager,
            tls_acceptor,
        })
    }

    /// Start the WebSocket server
    pub async fn run(self) -> Result<()> {
        let listener = TcpListener::bind(self.config.bind_addr).await?;
        info!("WebSocket server listening on {}", self.config.bind_addr);
        info!("TLS 1.3 only, cipher suites: TLS_AES_256_GCM_SHA384, TLS_AES_128_GCM_SHA256, TLS_CHACHA20_POLY1305_SHA256");

        let server = Arc::new(self);
        let connection_count = Arc::new(tokio::sync::Semaphore::new(server.config.max_connections));

        loop {
            // Acquire connection permit (blocks if max connections reached)
            let permit = connection_count.clone().acquire_owned().await
                .map_err(|e| ServerError::Internal(format!("Failed to acquire connection permit: {}", e)))?;

            match listener.accept().await {
                Ok((stream, peer_addr)) => {
                    let server = Arc::clone(&server);

                    // Spawn connection handler
                    tokio::spawn(async move {
                        info!("New connection from {}", peer_addr);

                        if let Err(e) = server.handle_connection(stream, peer_addr).await {
                            error!("Connection error from {}: {}", peer_addr, e);
                        }

                        drop(permit); // Release connection slot
                    });
                }
                Err(e) => {
                    error!("Failed to accept connection: {}", e);
                }
            }
        }
    }

    /// Handle a single connection
    async fn handle_connection(
        &self,
        stream: tokio::net::TcpStream,
        peer_addr: SocketAddr,
    ) -> Result<()> {
        // TLS handshake
        let tls_stream = self.tls_acceptor.accept(stream).await
            .map_err(|e| ServerError::TlsHandshake(e.to_string()))?;

        info!("TLS handshake completed with {}", peer_addr);

        // WebSocket upgrade
        let ws_stream = tokio_tungstenite::accept_async(tls_stream).await
            .map_err(|e| ServerError::WebSocketUpgrade(e.to_string()))?;

        info!("WebSocket handshake completed with {}", peer_addr);

        // Handle WebSocket messages
        handler::handle_websocket(ws_stream, peer_addr, Arc::clone(&self.session_manager)).await
    }
}

