/**
 * PWA Icon Generator for MONOTERMINAL
 * Generates required PWA icons from a source SVG or PNG
 *
 * Required icons per SRS §2.2:
 * - favicon.ico (16x16, 32x32, 48x48)
 * - pwa-192x192.png
 * - pwa-512x512.png
 * - apple-touch-icon.png (180x180)
 *
 * Usage:
 *   node scripts/generate-pwa-icons.js
 *
 * Note: For Phase 1, we'll create a simple placeholder.
 * For production, replace with actual branding.
 */

import { writeFileSync } from 'fs';
import { join } from 'path';

const PUBLIC_DIR = join(process.cwd(), 'public');

// Simple SVG template for placeholder icon
const createPlaceholderSVG = (size) => `<?xml version="1.0" encoding="UTF-8"?>
<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" xmlns="http://www.w3.org/2000/svg">
  <rect width="${size}" height="${size}" fill="#1e1e1e"/>
  <rect x="${size * 0.1}" y="${size * 0.1}" width="${size * 0.8}" height="${size * 0.8}" rx="${size * 0.05}" fill="#2472c8"/>
